declare(strict_types=1);

namespace App\Tests\Unit\Command\Worker\DeliveryExecution;

use App\Command\DeliveryExecution\DeliveryExecutionImport;
use App\Domain\Delivery\Model\Delivery;
use App\Repository\DeliveryRepository;
use App\Service\DeliveryExecution\SynchronizeDeliveryExecutionService;
use PHPUnit\Framework\MockObject\MockObject;
use PHPUnit\Framework\TestCase;
use Psr\EventDispatcher\EventDispatcherInterface;
use Symfony\Component\Console\Application;
use Symfony\Component\Console\Tester\CommandTester;
use ZipArchive;

class DeliveryExecutionImportTest extends TestCase
{
    private const CONSOLE_COMMAND_NAME = 'delivery-execution:import';
    private const QTI_COMPILED_DIR = '/tmp';
    private DeliveryExecutionImport $subject;
    private MockObject|SynchronizeDeliveryExecutionService $createDeliveryExecutionServiceMock;
    private MockObject|DeliveryRepository $deliveryRepositoryMock;
    private MockObject|EventDispatcherInterface $eventDispatcherMock;
    private MockObject|ZipArchive $zipArchiveMock;


    protected function setUp(): void
    {
        $this->zipArchiveMock = $this->createMock(ZipArchive::class);
        $this->createDeliveryExecutionServiceMock = $this->createMock(SynchronizeDeliveryExecutionService::class);
        $this->deliveryRepositoryMock = $this->createMock(DeliveryRepository::class);
        $this->eventDispatcherMock = $this->createMock(EventDispatcherInterface::class);

        $this->subject = new DeliveryExecutionImport(
            $this->createDeliveryExecutionServiceMock,
            $this->deliveryRepositoryMock,
            $this->eventDispatcherMock,
            $this->zipArchiveMock,
            self::QTI_COMPILED_DIR,
        );
    }

    public function testExecuteHandlesInvalidArgumentException(): void
    {
        $this->zipArchiveMock
            ->expects(self::once())
            ->method('open')
            ->willReturn(false);

        $commandTester = $this->executeCommand($this->subject);

        $this->assertStringContainsString('Cannot extract qti compile files', $commandTester->getDisplay());
    }

    public function testZipExtracted(): void
    {
        $this->zipArchiveMock
            ->expects(self::once())
            ->method('open')
            ->willReturn(true);

        $this->zipArchiveMock
            ->expects(self::once())
            ->method('extractTo')
            ->willReturn(true);

        $this->zipArchiveMock
            ->expects(self::once())
            ->method('close');

        $this->executeCommand($this->subject);
    }

    public function testCreateDelivery(): void
    {
        $deliveryId = 'f6bc40b4e1ac';
        $tenantId = 'local-dev-acc.nextgen-stack-local';
        $compactTestFilePath = 'f6bc40b4e1ac/compact-test.xml';
        $configuration = [
            "expiryDate" => null,
            "metadata" => null,
            "availabilityDate" => null,
            "label" => "Basic Test (Linear-Individual)",
            "status" => true,

        ];
        $qtiItemsMapping = [];
        $packageRef = '';

        $this->deliveryRepositoryMock
            ->expects($this->once())
            ->method('save');

        $this->eventDispatcherMock
            ->expects($this->once())
            ->method('dispatch');

        $method = $this->getPrivateMethod($this->subject, 'createDelivery');
        $result = $method->invokeArgs($this->subject, [
            $deliveryId,
            $tenantId,
            $compactTestFilePath,
            $configuration,
            $qtiItemsMapping,
            $packageRef,
        ]);

        $this->assertInstanceOf(Delivery::class, $result);
    }

    private function executeCommand(DeliveryExecutionImport $command, array $arguments = []): CommandTester
    {
        $application = new Application();
        $application->add($command);

        $command = $application->find(self::CONSOLE_COMMAND_NAME);
        $commandTester = new CommandTester($command);

        $arguments = array_merge([
            'command' => $command->getName(),
            'tenantId' => 'test',
            'encodedDeliveryExecutionData' => $this->getBase64MockString(),
        ], $arguments);

        $commandTester->execute($arguments);

        return $commandTester;
    }

    private function getPrivateMethod($classInstance, $methodName): \ReflectionMethod
    {
        $reflection = new \ReflectionClass($classInstance);
        $method = $reflection->getMethod($methodName);
        $method->setAccessible(true);

        return $method;
    }

    private function getBase64MockString(): string
    {
        return '';
    }
}
